    R"(<!doctype html><html><head><meta content='text/html; charset=UTF-8' http-equiv='content-type' /><meta name='VIEWPORT' content='width=device-width, initial-scale=1.0' /><style> body { margin: 0; font-size: 16px; font-weight: 400; line-height: 1.5; color: #212529; text-align: left; background-color: #fff; } .tabs { font-size: 0; max-width: 400px; margin-left: auto; margin-right: auto; } .tabs > h3 { font-size: 18pt; text-align: center; } .tabs > input[type='radio'] { display: none; } .tabs > input[type='radio']:checked + label { background-color: #cfcfcf; border-bottom: 1px solid #fff; } .tabs > label { display: inline-block; text-align: center; vertical-align: middle; user-select: none; background-color: #f5f5f5; border: 1px solid #e0e0e0; padding: 2px 8px; font-size: 16px; line-height: 1.5; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out; cursor: pointer; position: relative; top: 1px; } .tabs > div { /*скрыть контент по умолчанию*/ display: none; border: 2px solid #e0e0e0; padding: 10px 15px; font-size: 16px; } .tabs > label:not(:first-of-type) { border-left: none; } /*отобразить контент,связанный с выбранной радиокнопкой(input type='radio')*/ #tab-btn-1:checked ~ #relay_list, #tab-btn-2:checked ~ #setup_list { display: block; } #relay_list, #setup_list { border: 2px solid #e0e0e0; padding: 10px 15px; font-size: 16px; } #relay_list > h4, #setup_list > h4 { margin-left: 10px; } label { margin-left: 10px; } input[type='text'], input[type='number'] { display: block; margin-bottom: 10px; margin-left: 10px; width: 300px; } #label { display: none; } .save_btn { margin: 20px 25px; width: 120px; } .btn_right { margin-left: 20px; } .rst_btn { margin: 40px 10px 20px 10px; width: 200px; } </style></head><body><p id='label'></p><div class='tabs'><h3 id='h3'></h3><input type='radio' name='tab-btn' id='tab-btn-1' value='' checked /><label for='tab-btn-1'>Список реле</label ><input type='radio' name='tab-btn' id='tab-btn-2' value='' /><label for='tab-btn-2' >Настройки</label ><div id='relay_list'><h4 id='h4'></h4></div><div id='setup_list'><h4>Сетевые настройки модуля</h4><label>Имя модуля</label><input type='text' id='module_name' maxlength='16' placeholder='Имя модуля' /><label>Описание модуля</label><input type='text' id='module_descr' maxlength='64' placeholder='Описание модуля' /><label>Порт для приема/отправки пакетов</label><input type='number' max='65535' min='1' id='udp_port' maxlength='64' placeholder='Порт UDP' /><h4>Прочие настройки</h4><label id='save_last_state' style='margin: 15px 10px; display: block'><input type='checkbox' id='save_state' style='margin-left: 0px' /> Сохранять состояние реле при перезагрузке</label ><label id='check_int_l'>Интервал проверки удаленных реле, минут</label><input type='number' max='1800' min='0' id='check_int' maxlength='64' placeholder='Интервал проверки удаленных реле' /><input type='button' id='btn_rst' class='rst_btn' value='Перезагрузить модуль' onclick='restartESP()' /></div><input type='button' value='Назад' class='save_btn' onclick='window.open("/", "_self", false)' /><input type='button' id='btn_save' class='save_btn btn_right' value='Сохранить' onclick='sendData()' disabled /></div><script> var dest; function showAlert(doc) { if ( doc.value.length > 0 && (doc.value.length < 6 || doc.value.length > 16) ) { alert( 'Длина имени должна быть не менее 6 и не более 16 символов! \n\n Разрешенные символы: 0..9, A..Z, a..z, - , _', ); doc.focus(); return false; } return true; } function checkName() { var relays = document .getElementById('relay_list') .getElementsByClassName('relay'); for (var i = 0, len = relays.length; i < len; i++) { if (!showAlert(relays[i])) { return false; } } if (!showAlert(document.getElementById('module_name'))) return false; return true; } function sendData() { if (!checkName()) { return; } document.getElementById('btn_save').disabled = 'disabled'; var values = []; var relays = document .getElementById('relay_list') .getElementsByClassName('relay'); var descrs = document .getElementById('relay_list') .getElementsByClassName('descr'); for (var i = 0, len = relays.length; i < len; ++i) { let rel = { name: relays[i].value, descr: descrs[i].value }; values.push(rel); } var f_data = { for: dest, module_descr: document.getElementById('module_descr').value, module_name: document.getElementById('module_name').value, udp_port: document.getElementById('udp_port').value, save_state: document.getElementById('save_state').checked, check_int: document.getElementById('check_int').value, relays: values, }; var xhr = new XMLHttpRequest(); xhr.open('POST', '/sr_setconfig', true); xhr.setRequestHeader('Content-Type', 'text/json'); xhr.onreadystatechange = function () { document.body.innerHTML = this.responseText; }; xhr.send(JSON.stringify(f_data)); } function btnSaveEnabled() { document.getElementById('btn_save').removeAttribute('disabled'); } function getConfig() { var c_lab = document.getElementById('label'); var c_page = c_lab.innerHTML; c_lab.innerHTML = ''; var request = new XMLHttpRequest(); request.open('GET', c_page, true); request.onload = function () { if (request.readyState == 4 && request.status == 200) { var config_str = request.responseText; var doc = JSON.parse(config_str); dest = doc.for; if (doc.module_descr != 'null') document.getElementById('module_descr').value = doc.module_descr; if (doc.module_name != 'null') document.getElementById('module_name').value = doc.module_name; document.getElementById('udp_port').value = doc.udp_port; document.getElementById('h3').innerHTML = dest == 'relay' ? 'Модуль WiFi-реле - настройка' : 'Модуль WiFi-выключателя - настройка'; document.getElementById('h4').innerHTML = dest == 'relay' ? 'Сетевые идентификаторы реле' : 'Идентификаторы удаленных реле'; var d = document.getElementById('relay_list'); if (dest != 'relay') { document.getElementById('save_last_state').style.display = 'none'; document.getElementById('check_int').value = doc.check_int; } else { document.getElementById('check_int').style.display = 'none'; document.getElementById('check_int_l').style.display = 'none'; doc.save_state == 1 ? document .getElementById('save_state') .setAttribute('checked', 'checked') : document .getElementById('save_state') .removeAttribute('checked'); } var mn = document.getElementById("module_name"); mn.addEventListener("input", (event) => { mn.value = mn.value.replace(/[^a-zA-Z0-9_/-]/g, ""); btnSaveEnabled(); }); for (var i = 0; i < doc.relays.length; i++) { const lab = document.createElement('label'); lab.innerHTML = dest == 'relay' ? 'Реле №' + String(i + 1) : 'Кнопка №' + String(i + 1); d.append(lab); const inp1 = document.createElement('input'); inp1.type = 'text'; inp1.maxLength = '16'; inp1.className = 'relay'; inp1.placeholder = 'Идентификатор реле'; inp1.addEventListener('input', (event) => { inp1.value = inp1.value.replace(/[^a-zA-Z0-9_/-]/g, ''); btnSaveEnabled(); }); inp1.value = doc.relays[i].name; d.append(inp1); const inp2 = document.createElement('input'); inp2.type = 'text'; inp2.maxLength = '64'; inp2.className = 'descr'; inp2.placeholder = 'Описание реле'; if (dest == 'switch') { inp2.disabled = true; } inp2.addEventListener('input', (event) => btnSaveEnabled()); inp2.value = doc.relays[i].descr; d.append(inp2); } } }; request.send(); } function restartESP() { if (!document.getElementById("btn_save").hasAttribute("disabled")) { if ( !confirm('Настройки были изменены. Все равно перезагрузить модуль?') ) return; } else { if (!confirm('Вы действительно хотите перезагрузить модуль?')) return; } var request = new XMLHttpRequest(); request.open('GET', '/sr_restart', true); request.onload = function () { document.body.innerHTML = '<p align="center">Module restart...</p>'; setTimeout(function () { window.location.href = '/'; }, 5 * 1000); }; request.send(); } document .getElementById('module_descr') .addEventListener('input', btnSaveEnabled); document .getElementById('udp_port') .addEventListener('input', btnSaveEnabled); document .getElementById('save_state') .addEventListener('input', btnSaveEnabled); document .getElementById('check_int') .addEventListener('input', btnSaveEnabled); document.addEventListener('DOMContentLoaded', getConfig); </script></body></html>)";